<?php
require_once __DIR__ . '/../lib/bootstrap.php';
require_once __DIR__ . '/../lib/exam_randomizer.php';
require_role('teacher','admin');
$uid=(int)current_user()['id'];$id=get_int('id');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=post_string('action');$id=(int)($_POST['exam_id']??$id);
 if($action==='create_exam'){
  $subjectId=(int)($_POST['subject_id']??0);
  $classId=(int)($_POST['class_id']??0);
  $allowed=current_user()['role']==='admin';
  if(!$allowed){
   $allowed=teacher_can_use_subject_for_class($uid,$subjectId,$classId);
  }
  if(!$allowed){flash('error','شما به این کلاس منتسب نیستید.');redirect('teacher/exams.php');}

  $available=[];
  foreach(db()->query('SHOW COLUMNS FROM exams') as $column){$available[$column['Field']]=true;}
  $requiredColumns=['max_attempts','score_policy','chapter','random_per_student','random_easy_count','random_medium_count','random_hard_count'];
  if(array_diff($requiredColumns,array_keys($available))){flash('error','ابتدا migration جدید آزمون‌های تصادفی را اجرا کنید: install/migrations/20261116_per_student_random_questions.sql');redirect('teacher/exams.php');}
  $randomMode=(int)($_POST['random_per_student']??1)===1?1:0;
  $chapter=trim(post_string('chapter',150));
  $randomCounts=[];
  foreach(['easy'=>'random_easy_count','medium'=>'random_medium_count','hard'=>'random_hard_count'] as $level=>$field){$raw=(string)($_POST[$field]??'0');if(!preg_match('/^\d+$/',$raw)||(int)$raw>500){flash('error','تعداد هر سطح باید عدد صحیحی بین صفر تا ۵۰۰ باشد.');redirect('teacher/exams.php');}$randomCounts[$level]=(int)$raw;}
  if($randomMode){
   if($chapter===''){flash('error','برای انتخاب تصادفی، پودمان سؤال‌ها را انتخاب کنید.');redirect('teacher/exams.php');}
   if(array_sum($randomCounts)<1||array_sum($randomCounts)>500){flash('error','مجموع سهمیهٔ سؤال‌ها باید بین ۱ تا ۵۰۰ باشد.');redirect('teacher/exams.php');}
   $chapterCheck=db()->prepare("SELECT COUNT(*) FROM question_bank WHERE subject_id=? AND is_active=1 AND chapter IS NOT NULL AND TRIM(chapter)=TRIM(?)");$chapterCheck->execute([$subjectId,$chapter]);if((int)$chapterCheck->fetchColumn()<1){flash('error','برای این درس و پودمان سؤال فعال در بانک پیدا نشد.');redirect('teacher/exams.php');}
  }
  $examData=[
   'subject_id'=>$subjectId,
   'chapter'=>$randomMode?$chapter:null,
   'random_per_student'=>$randomMode,
   'random_easy_count'=>$randomMode?$randomCounts['easy']:0,
   'random_medium_count'=>$randomMode?$randomCounts['medium']:0,
   'random_hard_count'=>$randomMode?$randomCounts['hard']:0,
   'class_id'=>$classId,
   'title'=>post_string('title',200),
   'instructions'=>post_string('instructions'),
   'duration_minutes'=>max(1,(int)($_POST['duration_minutes']??30)),
   'total_score'=>(float)($_POST['total_score']??20),
   'starts_at'=>post_string('starts_at')?:null,
   'ends_at'=>post_string('ends_at')?:null,
   'created_by'=>$uid,
  ];
  if(isset($available['max_attempts'])){
   $examData['max_attempts']=1;
  }
  if(isset($available['score_policy'])){
   $examData['score_policy']='best';
  }
  $columns=array_keys($examData);
  $placeholders=implode(',',array_fill(0,count($columns),'?'));
  $s=db()->prepare('INSERT INTO exams('.implode(',',$columns).') VALUES('.$placeholders.')');
  $s->execute(array_values($examData));
  $id=(int)db()->lastInsertId();
  flash('success',$randomMode?'آزمون با انتخاب تصادفی شخصی‌سازی‌شده ساخته شد؛ سهمیه‌ها را بررسی و سپس منتشر کنید.':'آزمون ایجاد شد؛ اکنون پرسش اضافه کنید.');
  redirect('teacher/exams.php?id='.$id);
 }
 if($action==='back_to_draft'){
  $targetId=(int)($_POST['exam_id']??$id);
  $ownerSql=current_user()['role']==='admin'?'':' AND created_by=?';
  $ownerParams=current_user()['role']==='admin'?[$targetId]:[$targetId,$uid];
  $find=db()->prepare("SELECT id,status,random_per_student FROM exams WHERE id=?$ownerSql");$find->execute($ownerParams);$targetExam=$find->fetch();
  if(!$targetExam){flash('error','آزمون پیدا نشد یا دسترسی لازم را ندارید.');}
  elseif($targetExam['status']!=='published'){flash('error','فقط آزمون منتشرشده را می‌توان به پیش‌نویس برگرداند.');}
  elseif((int)$targetExam['random_per_student']===1){$attemptCountCheck=db()->prepare('SELECT COUNT(*) FROM attempts WHERE exam_id=?');$attemptCountCheck->execute([$targetId]);if((int)$attemptCountCheck->fetchColumn()>0){flash('error','پس از آغاز تلاش‌ها، آزمون تصادفی برای حفظ نسخهٔ سؤال‌ها قابل بازگشت به حالت ویرایش نیست.');redirect('teacher/exams.php?id='.$targetId);}$stmt=db()->prepare("UPDATE exams SET status='draft' WHERE id=?");$stmt->execute([$targetId]);audit('unpublish_exam','exam',$targetId);flash('success','آزمون به پیش‌نویس برگشت.');}
  else{$stmt=db()->prepare("UPDATE exams SET status='draft' WHERE id=?");$stmt->execute([$targetId]);audit('unpublish_exam','exam',$targetId);flash('success','آزمون به پیش‌نویس برگشت. اکنون می‌توانید سؤال‌ها را ویرایش کنید و پس از بررسی دوباره منتشر کنید.');}
  redirect('teacher/exams.php?id='.$targetId);
 }
 if($action==='delete_exam'){
  $deleteId=(int)($_POST['exam_id']??0);
  $ownerSql=current_user()['role']==='admin'?'':' AND created_by=?';
  $ownerParams=current_user()['role']==='admin'?[$deleteId]:[$deleteId,$uid];
  $find=db()->prepare("SELECT id,status FROM exams WHERE id=?$ownerSql");$find->execute($ownerParams);$targetExam=$find->fetch();
  if(!$targetExam){flash('error','آزمون پیدا نشد یا دسترسی حذف آن را ندارید.');redirect('teacher/');}
  elseif($targetExam['status']!=='draft'){flash('error','برای حفظ سوابق دانش‌آموزان، فقط آزمون‌های پیش‌نویس قابل حذف هستند.');redirect('teacher/');}
  else{
   $attempts=db()->prepare('SELECT COUNT(*) FROM attempts WHERE exam_id=?');$attempts->execute([$deleteId]);
   if((int)$attempts->fetchColumn()>0){flash('error','این آزمون سابقه پاسخ دارد و قابل حذف نیست.');redirect('teacher/');}
   $pdo=db();$pdo->beginTransaction();
   try{
    $pdo->prepare('DELETE qo FROM question_options qo JOIN questions q ON q.id=qo.question_id WHERE q.exam_id=?')->execute([$deleteId]);
    $pdo->prepare('DELETE FROM questions WHERE exam_id=?')->execute([$deleteId]);
    $pdo->prepare('DELETE FROM exams WHERE id=?')->execute([$deleteId]);
    $pdo->commit();flash('success','آزمون با موفقیت حذف شد.');
   }catch(Throwable $e){$pdo->rollBack();flash('error','حذف آزمون انجام نشد.');}
   redirect('teacher/');
  }
 }

 if(in_array($action,['add_question','auto_generate'],true)){ $draftCheck=db()->prepare('SELECT status,random_per_student FROM exams WHERE id=? AND (created_by=? OR ?=1)');$draftCheck->execute([$id,$uid,current_user()['role']==='admin'?1:0]);$draftExam=$draftCheck->fetch();if(!$draftExam||$draftExam['status']!=='draft'){flash('error','افزودن یا تولید سؤال فقط برای آزمون پیش‌نویس مجاز است.');redirect('teacher/exams.php?id='.$id);}if((int)$draftExam['random_per_student']===1){flash('error','این آزمون از بانک سؤال برای هر دانش‌آموز مجموعه می‌سازد؛ سؤال ثابت اضافه نکنید.');redirect('teacher/exams.php?id='.$id);}} if($action==='add_question'){$type=post_string('question_type');$orderStmt=db()->prepare('SELECT COALESCE(MAX(sort_order),0)+1 FROM questions WHERE exam_id=?');$orderStmt->execute([$id]);$nextOrder=(int)$orderStmt->fetchColumn();$s=db()->prepare('INSERT INTO questions(exam_id,question_text,question_type,score,sort_order,feedback,reference_answer,rubric) VALUES(?,?,?,?,?,?,?,?)');$s->execute([$id,post_string('question_text'),$type,(float)($_POST['score']??1),$nextOrder,post_string('feedback'),post_string('reference_answer'),post_string('rubric')]);$qid=(int)db()->lastInsertId();if(in_array($type,['mcq','true_false'],true)){ $opts=$type==='true_false'?['A'=>'درست','B'=>'نادرست']:['A'=>post_string('option_a',500),'B'=>post_string('option_b',500),'C'=>post_string('option_c',500),'D'=>post_string('option_d',500)];$correct=post_string('correct_key');$n=0;foreach($opts as $k=>$v){if($v!==''){$x=db()->prepare('INSERT INTO question_options(question_id,option_text,option_key,is_correct,sort_order) VALUES(?,?,?,?,?)');$x->execute([$qid,$v,$k,$k===$correct?1:0,$n++]);}}}flash('success','پرسش افزوده شد.');redirect('teacher/exams.php?id='.$id);}
 if($action==='auto_generate'){$chapter=post_string('chapter',150);$difficulty=post_string('difficulty');$types=['mcq','true_false','short'];$counts=['mcq'=>max(0,(int)($_POST['count_mcq']??0)),'true_false'=>max(0,(int)($_POST['count_true_false']??0)),'short'=>max(0,(int)($_POST['count_short']??0))];$pdo=db();$added=0;$orderStmt=$pdo->prepare('SELECT COALESCE(MAX(sort_order),0)+1 FROM questions WHERE exam_id=?');$orderStmt->execute([$id]);$order=(int)$orderStmt->fetchColumn();$pdo->beginTransaction();try{foreach($types as $type){$n=$counts[$type]??0;if($n<1)continue;$sql='SELECT * FROM question_bank b WHERE b.subject_id=(SELECT subject_id FROM exams WHERE id=?) AND b.is_active=1 AND b.question_type=? AND NOT EXISTS (SELECT 1 FROM questions eq WHERE eq.exam_id=? AND eq.question_text=b.question_text)';$p=[$id,$type,$id];if($chapter!==''){$sql.=' AND chapter LIKE ?';$p[]='%'.$chapter.'%';}if(in_array($difficulty,['easy','medium','hard'],true)){$sql.=' AND difficulty=?';$p[]=$difficulty;}$sql.=' ORDER BY RAND() LIMIT '.(int)$n;$st=$pdo->prepare($sql);$st->execute($p);foreach($st as $bank){$q=$pdo->prepare('INSERT INTO questions(exam_id,question_text,chapter,image_path,question_type,score,difficulty,tags,sort_order,reference_answer,rubric) VALUES(?,?,?,?,?,?,?,?,?,?,?)');$q->execute([$id,$bank['question_text'],$bank['chapter']??null,$bank['image_path']??null,$bank['question_type'],$bank['score'],$bank['difficulty']??'medium',$bank['tags']??null,$order++,$bank['reference_answer'],$bank['rubric']]);$new=(int)$pdo->lastInsertId();$os=$pdo->prepare('SELECT * FROM question_bank_options WHERE bank_question_id=? ORDER BY sort_order,id');$os->execute([$bank['id']]);$oi=$pdo->prepare('INSERT INTO question_options(question_id,option_text,image_path,option_key,is_correct,sort_order) VALUES(?,?,?,?,?,?)');foreach($os as $o)$oi->execute([$new,$o['option_text'],$o['image_path']??null,$o['option_key'],$o['is_correct'],$o['sort_order']]);$added++;}}$pdo->commit();flash('success',$added.' سؤال به‌صورت خودکار اضافه شد.');}catch(Throwable $e){$pdo->rollBack();flash('error','تولید خودکار انجام نشد: '.$e->getMessage());}redirect('teacher/exams.php?id='.$id);} if($action==='delete_selected_questions'){
