   elseif($examTarget['status']!=='draft'){flash('error','حذف گروهی سؤال فقط برای آزمون پیش‌نویس مجاز است.');}elseif((int)$examTarget['random_per_student']===1){flash('error','سؤال‌های این آزمون از بانک و بر اساس سهمیه انتخاب می‌شوند؛ حذف گروهی در دسترس نیست.');}
   else{
    $marks=implode(',',array_fill(0,count($selected),'?'));$pdo=db();$pdo->beginTransaction();
    try{$pdo->prepare("DELETE qo FROM question_options qo JOIN questions q ON q.id=qo.question_id WHERE q.exam_id=? AND q.id IN ($marks)")->execute(array_merge([$id],$selected));$pdo->prepare("DELETE FROM questions WHERE exam_id=? AND id IN ($marks)")->execute(array_merge([$id],$selected));$pdo->commit();flash('success',count($selected).' سؤال از آزمون حذف شد.');}
    catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error','حذف گروهی سؤال‌ها انجام نشد.');}
   }
  }
  redirect('teacher/exams.php?id='.$id.'&section=existing');
 }
