ansaction();try{$pdo->prepare('DELETE FROM question_options WHERE question_id=?')->execute([$qId]);$pdo->prepare('DELETE FROM questions WHERE id=? AND exam_id=?')->execute([$qId,$id]);$pdo->commit();flash('success','پرسش از آزمون حذف شد.');}catch(Throwable $e){$pdo->rollBack();flash('error','حذف پرسش انجام نشد.');}}else if($action==='update_question_score'){$score=max(0.01,(float)($_POST['score']??0));$s=db()->prepare('UPDATE questions SET score=? WHERE id=? AND exam_id=?');$s->execute([$score,$qId,$id]);flash('success','نمرهٔ پرسش تغییر کرد.');}else{$direction=post_string('direction');$cmp=$direction==='up'?'<':'>';$sort=$direction==='up'?'DESC':'ASC';$neighbor=db()->prepare("SELECT id,sort_order FROM questions WHERE exam_id=? AND sort_order $cmp ? ORDER BY sort_order $sort LIMIT 1");$neighbor->execute([$id,$target['sort_order']]);$other=$neighbor->fetch();if($other){$pdo=db();$pdo->beginTransaction();$tmp=-1;$pdo->prepare('UPDATE questions SET sort_order=? WHERE id=?')->execute([$tmp,$qId]);$pdo->prepare('UPDATE questions SET sort_order=? WHERE id=?')->execute([$target['sort_order'],$other['id']]);$pdo->prepare('UPDATE questions SET sort_order=? WHERE id=?')->execute([$other['sort_order'],$qId]);$pdo->commit();flash('success','ترتیب پرسش تغییر کرد.');}}redirect('teacher/exams.php?id='.$id);} if($action==='save_random_settings'){
