  $chapter=trim(post_string('chapter',150));$counts=[];foreach(['easy'=>'random_easy_count','medium'=>'random_medium_count','hard'=>'random_hard_count'] as $level=>$field){$raw=(string)($_POST[$field]??'0');if(!preg_match('/^\\d+$/',$raw)||(int)$raw>500){$counts[$level]=-1;}else{$counts[$level]=(int)$raw;}}
  if(!$settingsExam||$settingsExam['status']!=='draft'||(int)$settingsExam['random_per_student']!==1){flash('error','تنظیم سهمیه فقط برای آزمون تصادفیِ پیش‌نویس مجاز است.');}
  else{$attemptCountCheck=db()->prepare('SELECT COUNT(*) FROM attempts WHERE exam_id=?');$attemptCountCheck->execute([$id]);
   if((int)$attemptCountCheck->fetchColumn()>0){flash('error','پس از شروع تلاش دانش‌آموزان، ترکیب سؤال‌ها قابل تغییر نیست تا کارنامه‌ها ثابت بمانند.');}
   elseif(array_sum($counts)<1||array_sum($counts)>500||in_array(-1,$counts,true)){flash('error','سهمیه‌ها باید عدد صحیح باشند و مجموع آن‌ها بین ۱ تا ۵۰۰ باشد.');}
   else{$chapterCheck=db()->prepare("SELECT COUNT(*) FROM question_bank WHERE subject_id=? AND is_active=1 AND TRIM(chapter)=TRIM(?)");$chapterCheck->execute([(int)$settingsExam['subject_id'],$chapter]);if($chapter===''||(int)$chapterCheck->fetchColumn()<1){flash('error','پودمان انتخاب‌شده برای این درس سؤال فعال ندارد.');}else{$pdo=db();$pdo->beginTransaction();try{$pdo->prepare('DELETE qo FROM question_options qo JOIN questions q ON q.id=qo.question_id WHERE q.exam_id=?')->execute([$id]);$pdo->prepare('DELETE FROM questions WHERE exam_id=?')->execute([$id]);$pdo->prepare('UPDATE exams SET chapter=?,random_per_student=1,random_easy_count=?,random_medium_count=?,random_hard_count=? WHERE id=?')->execute([$chapter,$counts['easy'],$counts['medium'],$counts['hard'],$id]);$pdo->commit();audit('update_random_exam_settings','exam',$id);flash('success','پودمان و سهمیه‌های تصادفی آزمون ذخیره شد.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error','ذخیرهٔ تنظیمات آزمون انجام نشد.');}}}
