  redirect('teacher/exams.php?id='.$id);
 }}
if(current_user()['role']==='admin'){$subjects=db()->query('SELECT id,title FROM subjects WHERE is_active=1 ORDER BY title')->fetchAll();}else{$subjectStmt=db()->prepare('SELECT DISTINCT s.id,s.title FROM subjects s WHERE s.is_active=1 AND EXISTS (SELECT 1 FROM class_subjects cs WHERE cs.subject_id=s.id AND cs.teacher_id=?) ORDER BY s.title');$subjectStmt->execute([$uid]);$subjects=$subjectStmt->fetchAll();}if(current_user()['role']==='admin'){$classes=db()->query('SELECT id,title FROM classes ORDER BY title')->fetchAll();}else{$classStmt=db()->prepare('SELECT DISTINCT c.id,c.title FROM classes c JOIN class_subjects cs ON cs.class_id=c.id WHERE cs.teacher_id=? ORDER BY c.title');$classStmt->execute([$uid]);$classes=$classStmt->fetchAll();}$chapterOptions=[];$subjectIds=array_values(array_unique(array_map(static fn($subject)=>(int)$subject['id'],$subjects)));if($subjectIds){$chapterMarks=implode(',',array_fill(0,count($subjectIds),'?'));$chapterStmt=db()->prepare("SELECT DISTINCT subject_id,TRIM(chapter) chapter FROM question_bank WHERE is_active=1 AND chapter IS NOT NULL AND TRIM(chapter)<>'' AND subject_id IN ($chapterMarks) ORDER BY subject_id,chapter");$chapterStmt->execute($subjectIds);$chapterOptions=$chapterStmt->fetchAll();}$exam=null;$questions=[];$randomPool=['easy'=>0,'medium'=>0,'hard'=>0];$randomAttemptCount=0;if($id){$s=db()->prepare('SELECT e.*,s.title subject_title,c.title class_title FROM exams e JOIN subjects s ON s.id=e.subject_id JOIN classes c ON c.id=e.class_id WHERE e.id=? AND e.archived_at IS NULL');$s->execute([$id]);$exam=$s->fetch();$attemptCountStmt=db()->prepare('SELECT COUNT(*) FROM attempts WHERE exam_id=?');$attemptCountStmt->execute([$id]);$randomAttemptCount=(int)$attemptCountStmt->fetchColumn();$s=db()->prepare('SELECT q.*,GROUP_CONCAT(CONCAT(o.option_key,": ",o.option_text) ORDER BY o.sort_order SEPARATOR " | ") options_text FROM questions q LEFT JOIN question_options o ON o.question_id=q.id WHERE q.exam_id=? GROUP BY q.id ORDER BY q.sort_order');$s->execute([$id]);$questions=$s->fetchAll();$capacity=['mcq'=>0,'true_false'=>0,'short'=>0];$cs=db()->prepare('SELECT b.question_type,COUNT(*) total FROM question_bank b WHERE b.subject_id=? AND b.is_active=1 AND NOT EXISTS (SELECT 1 FROM questions eq WHERE eq.exam_id=? AND eq.question_text=b.question_text) GROUP BY b.question_type');$cs->execute([$exam['subject_id'],$id]);foreach($cs as $row)$capacity[$row['question_type']]=(int)$row['total'];if((int)($exam['random_per_student']??0)===1){$poolExists=db()->prepare('SELECT COUNT(*) FROM questions WHERE exam_id=? AND bank_question_id IS NOT NULL');$poolExists->execute([$id]);if((int)$poolExists->fetchColumn()>0){$poolStmt=db()->prepare('SELECT difficulty,COUNT(*) total FROM questions WHERE exam_id=? AND bank_question_id IS NOT NULL GROUP BY difficulty');$poolStmt->execute([$id]);}else{$poolStmt=db()->prepare("SELECT qb.difficulty,COUNT(*) total FROM question_bank qb WHERE qb.subject_id=? AND qb.is_active=1 AND TRIM(qb.chapter)=TRIM(?) AND (qb.question_type='short' OR (qb.question_type IN ('mcq','true_false') AND (SELECT COUNT(*) FROM question_bank_options o WHERE o.bank_question_id=qb.id)>=2 AND (SELECT COUNT(*) FROM question_bank_options o WHERE o.bank_question_id=qb.id AND o.is_correct=1)=1)) GROUP BY qb.difficulty");$poolStmt->execute([(int)$exam['subject_id'],(string)$exam['chapter']]);}foreach($poolStmt as $poolRow){if(isset($randomPool[$poolRow['difficulty']]))$randomPool[$poolRow['difficulty']]=(int)$poolRow['total'];}}}$title='مدیریت آزمون';require __DIR__.'/../partials/header.php';?><h1>مدیریت آزمون</h1><?php if(!$exam):?><div class="card"><h2>آزمون جدید</h2><form method="post" class="grid grid-2"><?=csrf_field()?><input type="hidden" name="action" value="create_exam"><div class="form-group"><label for="exam-subject-select">درس</label><select name="subject_id" id="exam-subject-select" required><option value="">انتخاب کنید</option><?php foreach($subjects as $s):?><option value="<?=$s['id']?>" <?=get_int('subject_id')===$s['id']?'selected':''?>><?=e($s['title'])?></option><?php endforeach;?></select></div><div class="form-group"><label>کلاس</label><select name="class_id" required><option value="">انتخاب کنید</option><?php foreach($classes as $c):?><option value="<?=$c['id']?>"><?=e($c['title'])?></option><?php endforeach;?></select></div><div class="form-group"><label>عنوان آزمون</label><input name="title" required></div><div class="form-group"><label>مدت به دقیقه</label><input type="number" name="duration_minutes" value="30" min="1"></div><div class="form-group"><label>نمره کل</label><input type="number" step="0.01" name="total_score" value="20"></div><div class="form-group"><label for="random-mode-select">روش ارائهٔ سؤال</label><select name="random_per_student" id="random-mode-select"><option value="1" selected>انتخاب تصادفی متفاوت برای هر دانش‌آموز</option><option value="0">سؤال‌های ثابت برای همهٔ دانش‌آموزان</option></select></div><div class="alert info" style="grid-column:1/-1;margin:0">هر دانش‌آموز یک تلاش عادی دارد؛ فرصت مجدد فقط با مجوز مدیر یا معلم فعال می‌شود و بهترین نمره ملاک نهایی است. در حالت تصادفی، سهمیهٔ هر تلاش جداگانه از بانک همان پودمان انتخاب و برای بررسی بعدی ثابت می‌شود.</div><div id="random-question-settings" style="grid-column:1/-1"><div class="grid grid-2"><div class="form-group"><label for="exam-chapter-select">پودمان / فصل بانک سؤال</label><select name="chapter" id="exam-chapter-select" required><option value="">ابتدا درس و سپس پودمان را انتخاب کنید</option><?php foreach($chapterOptions as $chapterOption):?><option value="<?=e($chapterOption['chapter'])?>" data-subject-id="<?=e((string)$chapterOption['subject_id'])?>"><?=e($chapterOption['chapter'])?></option><?php endforeach;?></select><small class="field-hint">فقط پودمان‌هایی نمایش داده می‌شوند که برای درس انتخاب‌شده سؤال فعال داشته باشند.</small></div><div class="form-group"><label>تعداد سؤال آسان برای هر دانش‌آموز</label><input type="number" name="random_easy_count" min="0" max="500" step="1" value="10" required></div><div class="form-group"><label>تعداد سؤال متوسط برای هر دانش‌آموز</label><input type="number" name="random_medium_count" min="0" max="500" step="1" value="10" required></div><div class="form-group"><label>تعداد سؤال دشوار / عمیق برای هر دانش‌آموز</label><input type="number" name="random_hard_count" min="0" max="500" step="1" value="10" required></div></div><p class="muted">مجموع سهمیهٔ هر برگه باید بین ۱ تا ۵۰۰ باشد. برای تضمین یک فرصت مجدد مجاز با سؤال‌های تازه، موجودی هر سطح باید دست‌کم دو برابر سهمیهٔ همان سطح باشد. انتخاب‌ها برای هر دانش‌آموز مستقل‌اند و ممکن است بین دانش‌آموزان هم‌پوشانی داشته باشند.</p></div><div class="form-group"><label>زمان شروع (اختیاری)</label><input type="datetime-local" name="starts_at"></div><div class="form-group"><label>زمان پایان (اختیاری)</label><input type="datetime-local" name="ends_at"></div><div class="form-group"><label>توضیحات</label><textarea name="instructions"></textarea></div><button class="btn btn-primary">ایجاد آزمون</button></form><script>(function(){var mode=document.getElementById('random-mode-select'),settings=document.getElementById('random-question-settings'),subject=document.getElementById('exam-subject-select'),chapter=document.getElementById('exam-chapter-select');if(!mode||!settings||!subject||!chapter)return;function filterChapters(){var subjectId=subject.value,selected=false;Array.prototype.forEach.call(chapter.options,function(option){if(!option.dataset.subjectId)return;option.hidden=!!subjectId&&option.dataset.subjectId!==subjectId;if(option.selected&&!option.hidden)selected=true;});if(!selected)chapter.value='';}function sync(){var enabled=mode.value==='1';settings.hidden=!enabled;Array.prototype.forEach.call(settings.querySelectorAll('input,select'),function(field){field.disabled=!enabled;if(field.name==='chapter')field.required=enabled;});if(enabled)filterChapters();}subject.addEventListener('change',filterChapters);mode.addEventListener('change',sync);sync();})();</script></div><?php else:?><div class="card"><h2><?=e($exam['title'])?></h2><p><?=e($exam['subject_title'])?> — <?=e($exam['class_title'])?> — وضعیت: <span class="badge"><?=e($exam['status'])?></span> | تلاش عادی: ۱ بار | ملاک نمره: بهترین تلاش</p><?php if($exam['status']==='draft'):?><form method="post" style="display:inline"><?=csrf_field()?><input type="hidden" name="action" value="publish"><button class="btn btn-success">انتشار آزمون</button></form><?php elseif($exam['status']==='published'&&((int)($exam['random_per_student']??0)!==1||$randomAttemptCount===0)):?><form method="post" style="display:inline" onsubmit="return confirm('آزمون موقتاً از دسترس دانش‌آموزان خارج شود و به پیش‌نویس برگردد؟ پاسخ‌های قبلی حذف نمی‌شوند.');"><?=csrf_field()?><input type="hidden" name="action" value="back_to_draft"><input type="hidden" name="exam_id" value="<?=$exam['id']?>"><button class="btn btn-warning">بازگشت به پیش‌نویس برای ویرایش</button></form><?php elseif($exam['status']==='published'&&(int)($exam['random_per_student']??0)===1):?><span class="muted">ویرایش ترکیب سؤال پس از شروع تلاش‌ها غیرفعال است.</span><?php endif;?><a class="btn btn-light" target="_blank" href="<?=e(url('teacher/preview_exam.php?id='.$id))?>">پیش‌نمایش آزمون</a><a class="btn btn-light" href="<?=e(url('teacher/review_short_answers.php?exam_id='.$id))?>">بررسی پاسخ کوتاه</a><a class="btn btn-light" href="<?=e(url('teacher/exam_report.php?exam_id='.$id))?>">گزارش آزمون</a><a class="btn btn-light" href="<?=e(url('teacher/attempts.php?exam_id='.$id))?>">مدیریت تلاش‌ها</a><?php if((int)($exam['random_per_student']??0)!==1):?><a class="btn btn-primary" href="<?=e(url('teacher/import_questions.php?exam_id='.$id))?>">ورود گروهی پرسش‌ها از Word</a><?php endif;?><a class="btn btn-primary" href="<?=e(url('teacher/question_bank.php?exam_id='.$id))?>">بانک سؤال</a></div><?php if((int)($exam['random_per_student']??0)===1):?><div class="card"><h2>ترکیب سؤال‌های شخصی‌سازی‌شده</h2><?php if($exam['status']==='draft'&&$randomAttemptCount===0):?><form method="post" class="grid grid-2" style="margin-bottom:18px"><?=csrf_field()?><input type="hidden" name="action" value="save_random_settings"><input type="hidden" name="exam_id" value="<?=$id?>"><div class="form-group"><label for="draft-random-chapter">پودمان / فصل</label><select name="chapter" id="draft-random-chapter" required><option value="">انتخاب پودمان</option><?php foreach($chapterOptions as $chapterOption):?><option value="<?=e($chapterOption['chapter'])?>" <?=((int)$chapterOption['subject_id']===(int)$exam['subject_id']&&trim((string)$exam['chapter'])===(string)$chapterOption['chapter'])?'selected':''?>><?=e($chapterOption['chapter'])?></option><?php endforeach;?></select></div><div class="form-group"><label>تعداد آسان</label><input type="number" name="random_easy_count" min="0" max="500" value="<?=e((string)$exam['random_easy_count'])?>" required></div><div class="form-group"><label>تعداد متوسط</label><input type="number" name="random_medium_count" min="0" max="500" value="<?=e((string)$exam['random_medium_count'])?>" required></div><div class="form-group"><label>تعداد دشوار / عمیق</label><input type="number" name="random_hard_count" min="0" max="500" value="<?=e((string)$exam['random_hard_count'])?>" required></div><div><button class="btn btn-light">ذخیرهٔ تنظیمات سؤال</button></div></form><?php endif;?><?php if($exam['status']==='draft'&&$randomAttemptCount>0):?><p class="muted">پس از شروع تلاش‌ها، تنظیمات برای حفظ ثبات سؤال‌ها و کارنامه‌ها قفل شده‌اند.</p><?php endif;?><p>هر دانش‌آموز برای هر تلاش از مجموعهٔ ثابتی که هنگام انتشار از بانک همین درس و پودمان تهیه می‌شود، سهمیهٔ تصادفی می‌گیرد.</p><p class="muted">پودمان: <strong><?=e((string)$exam['chapter'])?></strong> | مجموع برای هر تلاش: <strong><?=e((string)array_sum(exam_random_question_counts($exam)))?></strong> سؤال</p><div class="grid grid-3"><div class="stat-card"><strong><?=e((string)($exam['random_easy_count']??0))?> / <?=e((string)((int)($exam['random_easy_count']??0)*2))?> / <?=e((string)$randomPool['easy'])?></strong><span>سهمیهٔ هر تلاش / نیاز با یک مجدد / موجودِ آسان</span></div><div class="stat-card"><strong><?=e((string)($exam['random_medium_count']??0))?> / <?=e((string)((int)($exam['random_medium_count']??0)*2))?> / <?=e((string)$randomPool['medium'])?></strong><span>سهمیهٔ هر تلاش / نیاز با یک مجدد / موجودِ متوسط</span></div><div class="stat-card"><strong><?=e((string)($exam['random_hard_count']??0))?> / <?=e((string)((int)($exam['random_hard_count']??0)*2))?> / <?=e((string)$randomPool['hard'])?></strong><span>سهمیهٔ هر تلاش / نیاز با یک مجدد / موجودِ دشوار</span></div></div><p class="muted">برای انتشار، بانکِ ثابت‌شده باید برای هر سطح به اندازهٔ یک برگه و یک فرصت مجدد مجاز سؤالِ قابل‌استفاده داشته باشد. فرصت مجدد از سؤال‌های استفاده‌نشدهٔ همین pool انتخاب می‌کند.</p></div><?php else:?><div class="card"><h2>ظرفیت باقی‌مانده بانک سؤال</h2><p class="muted">این تعداد سؤال فعالِ همان درس است که هنوز در این آزمون استفاده نشده.</p><div class="grid grid-3"><div class="stat-card"><strong><?=e((string)$capacity['mcq'])?></strong><span>تستی</span></div><div class="stat-card"><strong><?=e((string)$capacity['true_false'])?></strong><span>صحیح/غلط</span></div><div class="stat-card"><strong><?=e((string)$capacity['short'])?></strong><span>پاسخ کوتاه</span></div></div></div><?php if($exam['status']==='draft'):?><details class="card exam-builder-panel"><summary class="exam-builder-summary"><span><strong>تولید خودکار از بانک سؤال</strong><small>انتخاب چند سؤال از بانک، بر اساس نوع و سطح دشواری</small></span><b>باز کردن</b></summary><div class="exam-builder-content"><h2>تولید خودکار از بانک سؤال</h2><p class="muted">سؤال‌ها به آزمون پیش‌نویس اضافه می‌شوند و قبل از انتشار قابل بازبینی هستند.</p><form method="post" class="grid grid-2"><?=csrf_field()?><input type="hidden" name="action" value="auto_generate"><div class="form-group"><label>فصل / مبحث اختیاری</label><input name="chapter" placeholder="مثلاً فصل دوم"></div><div class="form-group"><label>سطح دشواری</label><select name="difficulty"><option value="">همهٔ سطوح</option><option value="easy">آسان</option><option value="medium">متوسط</option><option value="hard">سخت</option></select></div><div class="form-group"><label>تعداد تستی</label><input type="number" name="count_mcq" value="0" min="0"></div><div class="form-group"><label>تعداد صحیح/غلط</label><input type="number" name="count_true_false" value="0" min="0"></div><div class="form-group"><label>تعداد پاسخ کوتاه</label><input type="number" name="count_short" value="0" min="0"></div><button class="btn btn-success">تولید و افزودن به آزمون</button></form></div></details><details class="card exam-builder-panel"><summary class="exam-builder-summary"><span><strong>افزودن پرسش دستی</strong><small>ثبت یک سؤال جدید برای همین آزمون</small></span><b>باز کردن</b></summary><div class="exam-builder-content"><h2>افزودن پرسش</h2><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="add_question"><div class="form-group"><label>متن پرسش</label><textarea name="question_text" required></textarea></div><div class="grid grid-2"><div class="form-group"><label>نوع</label><select name="question_type"><option value="mcq">چهارگزینه‌ای</option><option value="true_false">درست / نادرست</option><option value="short">تشریحی</option></select></div><div class="form-group"><label>نمره</label><input name="score" type="number" step="0.01" value="1"></div><div class="form-group"><label>پاسخ مرجع (برای سؤال تشریحی)</label><textarea name="reference_answer" placeholder="پاسخ کامل یا نمونهٔ مورد انتظار را بنویسید..."></textarea></div><div class="form-group"><label>معیارهای نمره‌دهی محلی</label><textarea name="rubric" placeholder="هر معیار در یک خط با قالب: عبارت کلیدی|نمره&#10;مثال: تعریف صحیح|1&#10;مثال اول|1"></textarea></div></div><div class="grid grid-2"><div class="form-group"><label>گزینه A</label><input name="option_a"></div><div class="form-group"><label>گزینه B</label><input name="option_b"></div><div class="form-group"><label>گزینه C</label><input name="option_c"></div><div class="form-group"><label>گزینه D</label><input name="option_d"></div><div class="form-group"><label>کلید پاسخ صحیح</label><select name="correct_key"><option value="A">A</option><option value="B">B</option><option value="C">C</option><option value="D">D</option></select></div></div><button class="btn btn-primary">افزودن پرسش</button></form></div></details><?php endif;?><?php endif;?><?php if((int)($exam['random_per_student']??0)===1):?><div class="card"><h2>سؤال‌های این آزمون</h2><p class="muted">این آزمون سؤال ثابت مشترک ندارد. برای هر تلاش، مجموعهٔ سؤال‌ها از بانک ساخته و همان نسخه در کارنامهٔ دانش‌آموز نگهداری می‌شود.</p></div><?php else:?><div class="card"><div class="questions-card-heading"><h2>پرسش‌های ثبت‌شده</h2><?php if($exam['status']==='draft'):?><form method="post" id="bulk-delete-questions" class="bulk-question-form" onsubmit="return confirm('سؤال‌های انتخاب‌شده از این آزمون حذف شوند؟ این عملیات قابل بازگشت نیست.');"><?=csrf_field()?><input type="hidden" name="action" value="delete_selected_questions"><input type="hidden" name="exam_id" value="<?=$id?>"><button class="btn btn-sm btn-danger" type="submit">حذف سؤال‌های انتخاب‌شده</button></form><?php endif;?></div><?php if($exam['status']==='draft' && $questions):?><div class="bulk-question-hint"><label><input type="checkbox" onchange="document.querySelectorAll('.exam-question-select').forEach(function(box){box.checked=this.checked}.bind(this))"> انتخاب همه سؤال‌ها</label><span class="muted">برای حذف چند سؤال، آن‌ها را علامت بزنید.</span></div><?php endif;?><?php foreach($questions as $i=>$q):?><?php $editOptions=[];$optionStmt=db()->prepare('SELECT option_key,option_text,is_correct FROM question_options WHERE question_id=? ORDER BY sort_order,id');$optionStmt->execute([(int)$q['id']]);foreach($optionStmt as $opt){$editOptions[$opt['option_key']]=$opt;}?><div class="question"><div class="question-prompt-row"><?php if($exam['status']==='draft'):?><label class="question-bulk-select"><input class="exam-question-select" type="checkbox" form="bulk-delete-questions" name="selected_questions[]" value="<?=$q['id']?>" aria-label="انتخاب سؤال <?=($i+1)?>"> انتخاب</label><?php endif;?><div class="question-prompt question-prompt-compact"><span class="question-number"><?=($i+1)?>.</span><?=question_prompt_html($q['question_text'])?></div></div><div class="muted">نوع: <?=e($q['question_type'])?> | نمره: <?=e($q['score'])?> | <?=e($q['options_text']??'')?></div><?php if($exam['status']==='draft'):?><div class="actions"><details class="exam-question-edit"><summary class="btn btn-sm btn-primary">ویرایش کامل سؤال</summary><form method="post" class="grid grid-2 exam-question-edit-form"><?=csrf_field()?><input type="hidden" name="action" value="update_question"><input type="hidden" name="question_id" value="<?=$q['id']?>"><div class="form-group"><label>متن سؤال</label><textarea class="question-editor" name="question_text" rows="10" dir="auto" spellcheck="false" required><?=e(question_editor_value($q['question_text']))?></textarea><small class="field-hint">صورت سؤال را در خط اول بنویسید و کد را از خط بعد وارد کنید؛ با Enter می‌توانید خطوط بیشتری اضافه کنید.</small></div><div class="form-group"><label>نوع سؤال</label><select name="question_type"><option value="mcq" <?=($q['question_type']==='mcq')?'selected':''?>>چهارگزینه‌ای</option><option value="true_false" <?=($q['question_type']==='true_false')?'selected':''?>>درست / نادرست</option><option value="short" <?=($q['question_type']==='short')?'selected':''?>>پاسخ کوتاه</option></select></div><div class="form-group"><label>نمره</label><input type="number" name="score" min="0.01" step="0.01" value="<?=e((string)$q['score'])?>" required></div><div class="form-group"><label>پاسخ مرجع</label><textarea name="reference_answer"><?=e($q['reference_answer']??'')?></textarea></div><div class="form-group"><label>Rubric / معیار نمره‌دهی</label><textarea name="rubric"><?=e($q['rubric']??'')?></textarea></div><div class="form-group"><label>بازخورد سؤال</label><textarea name="feedback"><?=e($q['feedback']??'')?></textarea></div><?php foreach(['A','B','C','D'] as $key):?><div class="form-group"><label>گزینهٔ <?=$key?></label><input name="option_<?=strtolower($key)?>" value="<?=e($editOptions[$key]['option_text']??'')?>"></div><?php endforeach;?><div class="form-group"><label>پاسخ صحیح</label><select name="correct_key"><?php foreach(['A','B','C','D'] as $key):?><option value="<?=$key?>" <?=(!empty($editOptions[$key]['is_correct']))?'selected':''?>><?=$key?></option><?php endforeach;?></select></div><button class="btn btn-success" type="submit">ذخیره ویرایش سؤال</button></form></details><form method="post" style="display:inline"><?=csrf_field()?><input type="hidden" name="action" value="update_question_score"><input type="hidden" name="question_id" value="<?=$q['id']?>"><input type="number" name="score" step="0.01" min="0.01" value="<?=e($q['score'])?>" style="width:90px"><button class="btn btn-sm btn-light">ذخیره نمره</button></form><form method="post" style="display:inline"><?=csrf_field()?><input type="hidden" name="action" value="move_question"><input type="hidden" name="question_id" value="<?=$q['id']?>"><input type="hidden" name="direction" value="up"><button class="btn btn-sm btn-light">↑</button></form><form method="post" style="display:inline"><?=csrf_field()?><input type="hidden" name="action" value="move_question"><input type="hidden" name="question_id" value="<?=$q['id']?>"><input type="hidden" name="direction" value="down"><button class="btn btn-sm btn-light">↓</button></form><form method="post" style="display:inline" onsubmit="return confirm('این پرسش از آزمون حذف شود؟')"><?=csrf_field()?><input type="hidden" name="action" value="delete_question"><input type="hidden" name="question_id" value="<?=$q['id']?>"><button class="btn btn-sm btn-danger">حذف</button></form></div><?php endif;?></div><?php endforeach;?></div><?php endif;?><?php endif;?><?php require __DIR__.'/../partials/footer.php'; ?>
